WITH filtered AS (SELECT *, ROUND(shipping_fee / amount, 2) amount_with_shipping FROM orders WHERE order_date >= DATE '2023-09-22') SELECT CASE WHEN amount >= 1750 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, status, ROUND(SUM(shipping_fee) / NULLIF(COUNT(CASE WHEN channel = 'web' THEN 1 END), 0), 2) AS shipping_fee_per_web, APPROX_PERCENTILE(amount_with_shipping, ARRAY(0.25, 0.5, 0.75)) AS amount_with_shipping_quartiles, SORT_ARRAY(COLLECT_SET(status)) AS status_list, DENSE_RANK() OVER (PARTITION BY CASE WHEN amount >= 1750 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY ROUND(SUM(shipping_fee) / NULLIF(COUNT(CASE WHEN channel = 'web' THEN 1 END), 0), 2) DESC) AS shipping_fee_per_web_dense_rank FROM filtered GROUP BY amount_tier, status HAVING shipping_fee_per_web >= 0;
